const NUMBER_OF_PARTICLES = 1000

function setup() {
	const width = windowWidth;
	const height = windowHeight;
	createCanvas(windowWidth, windowHeight);
	background(0);
	fill(255)
	// rect(windowWidth/2, 0, windowWidth, windowHeight)
	// rect(0, 0, windowWidth, windowHeight/2)
	// rect(windowWidth/2, 0, windowWidth, windowHeight/2)
	// rect(0, windowHeight/2, windowWidth/2, windowHeight)

	stroke(255);
	strokeWeight(1);
	frameRate(30)

	const minBound = createVector(0, 0);
	const maxBound = createVector(width,height);

	particles = []
	for (let i = 0; i < NUMBER_OF_PARTICLES; i++) {
		if (i < NUMBER_OF_PARTICLES / 3) {
			x = 3 * width/4
			y = height/2
		} else if (i < NUMBER_OF_PARTICLES * 2 / 3) {
			x = width/4
			y = height/2
		}
		else {
			x = width/2
			y = height / 2
		}
		particle = new Particle(x, y, [minBound, maxBound])
		particles.push(particle);
	}

