// === Tab: Particle ===
DV_FACTOR = 1

class Particle {

	constructor(x, y, bounds) {
		this.pos = createVector(x, y);
		this.v = createVector(0, 0);
		this.bounds = bounds
	}

	update() {
		// Update velocity vector
		let dv = createVector(random(DV_FACTOR) - DV_FACTOR/2, random(DV_FACTOR) - DV_FACTOR/2);
		this.v = this.v.add(dv);

		// Update position
		let newPosition = this.pos.add(this.v)
		let bounds = this.bounds

		// Max Bounds
		if (newPosition.x > bounds[1].x) { 
			newPosition.x = bounds[1].x + (bounds[1].x - newPosition.x);
			this.v.x = this.v.x * -1
		}

		if (newPosition.y > bounds[1].y) {
			newPosition.y = bounds[1].y + (bounds[1].y - newPosition.y)
			this.v.y = this.v.y * -1
		}

		// Min Bounds
		if (newPosition.x <= bounds[0].x) {
			newPosition.x = bounds[0].x + (bounds[0].x - newPosition.x)
			this.v.x = this.v.x * -1;
		}

		if (newPosition.y <= bounds[0].y) {
			newPosition.y = bounds[0].y + (bounds[0].y - newPosition.y)
			this.v.y = this.v.y * -1;
		}
	}

	draw() {
		// if ((this.pos.y > windowHeight/2) && (this.pos.x > windowWidth/2)) stroke(0)
		// else if ((this.pos.y > windowHeight / 2) && (this.pos.x < windowWidth / 2)) stroke(255)
		// else if ((this.pos.y < windowHeight / 2) && (this.pos.x < windowWidth / 2)) stroke(0)
		// else if ((this.pos.y < windowHeight / 2) && (this.pos.x > windowWidth / 2)) stroke(255)
		// else stroke(255, 0, 0)
		stroke(255,255,255)
		strokeWeight(1)
		point(this.pos.x, this.pos.y);
		if (frameCount < 120) {
			stroke(255,255,255,4)
			strokeWeight(8)
		} else {
			stroke(frameCount * 2.2 % 255, frameCount % 255, frameCount * 4.3 % 255, 12)
			strokeWeight(12);
		}
		point(this.pos.x, this.pos.y);
	}

}

